removeMenuButton.exampleCs:
// client

var rules = NativeUI.AddMenuButton("Rules", () => Events.ToServer("rules:show"));
NativeUI.RemoveMenuButton(rules);

createScreen.example:
// client
const board = kcds.ui.NativeUI.createScreen();

board.on('ready', () => {
  const panel = board.root.createClip();
  panel.draw([
    ['beginFill', 0x15130f, 80],
    ['moveTo', 0, 0],
    ['lineTo', 400, 0],
    ['lineTo', 400, 200],
    ['lineTo', 0, 200],
    ['endFill'],
  ]);
  const title = panel.createText({ x: 20, y: 20, width: 360, height: 40, text: 'Town board' });
  title.setTextStyle({ font: 'DisplayFont', size: 24 });
  board.setVisible(true);
});

createScreen.exampleCs:
// client
var board = NativeUI.CreateScreen();

board.On("ready", () =>
{
    var panel = board.Root.CreateClip();
    panel.Draw(new object[] { new object[] { "beginFill", 0x15130f, 80 }, new object[] { "moveTo", 0, 0 }, new object[] { "lineTo", 400, 0 }, new object[] { "lineTo", 400, 200 }, new object[] { "lineTo", 0, 200 }, new[] { "endFill" } });
    var title = panel.CreateText(new { x = 20, y = 20, width = 360, height = 40, text = "Town board" });
    title.SetTextStyle(new { font = "DisplayFont", size = 24 });
    board.SetVisible(true);
});

